{"command":"python3 -c "
import subprocess

code = '''
match {
  \"a\";
  either {
    \"b\";
    \"c\";
  }
  \"d\";
}
'''

res = subprocess.run(['./executable'], input=code.encode(), capture_output=True)
out = res.stdout.decode().strip()
err = res.stderr.decode().strip()
print('OUT:', repr(out))
print('ERR:', repr(err))
""}

