{"command":"cat <<'EOF' > /tmp/test_proj/src/main.rs
use pest::Parser;
use pest_derive::Parser;

#[derive(Parser)]
#[grammar_inline = r#"
WHITESPACE = _{ " " | "\t" | "\r" | "\n" }
COMMENT = _{ ("//" ~ (!"\n" ~ ANY)*) | ("/*" ~ (!"*/" ~ ANY)* ~ "*/") }

root = { SOI ~ statement* ~ EOI }

statement = {
    variable_declaration
  | quantifier
  | group
  | assertion
  | not_statement
  | range_statement
  | symbol_statement
  | literal_statement
  | raw_statement
  | variable_invocation
}

variable_declaration = { "let" ~ variable_name ~ "=" ~ block }
variable_invocation = { variable_name ~ ";" }
variable_name = @{ "." ~ (ASCII_ALPHA | "_") ~ (ASCII_ALPHANUMERIC | "_")* }

block = { "{" ~ statement* ~ "}" }

quantifier = { lazy? ~ amount ~ "of" ~ (block | atom_statement) }
lazy = { "lazy" }
amount = {
    range_amount
  | integer
  | "some"
  | "any"
  | "option"
}
range_amount = { integer ~ "to" ~ integer }
integer = @{ ASCII_DIGIT+ }

atom_statement = {
    symbol_content ~ ";"
  | range_content ~ ";"
  | literal_content ~ ";"
  | raw_content ~ ";"
  | not_content ~ ";"
  | variable_invocation
}

group = {
    "match" ~ block
  | "either" ~ block
  | "capture" ~ group_name? ~ block
}
group_name = @{ (ASCII_ALPHA | "_") ~ (ASCII_ALPHANUMERIC | "_")* }

assertion = {
  "not"? ~ assertion_type ~ block
}
assertion_type = { "ahead" | "behind" }

not_statement = { "not" ~ class_content ~ ";" }

class_content = {
    symbol_content
  | range_content
}

symbol_statement = { symbol_content ~ ";" }
symbol_content = ${ "<" ~ (ASCII_ALPHA | "_")+ ~ ">" }

range_statement = { range_content ~ ";" }
range_content = { range_bound ~ "to" ~ range_bound }
range_bound = @{ ASCII_ALPHANUMERIC }

literal_statement = { literal_content ~ ";" }
literal_content = ${ "\"" ~ double_quoted_inner ~ "\"" | "'" ~ single_quoted_inner ~ "'" }
double_quoted_inner = @{ ("\\\"" | "\\\\" | !"\"" ~ ANY)* }
single_quoted_inner = @{ ("\\'" | "\\\\" | !"'" ~ ANY)* }

raw_statement = { raw_content ~ ";" }
raw_content = ${ "`" ~ raw_inner ~ "`" }
raw_inner = @{ ("\\`" | "\\\\" | !"`" ~ ANY)* }
"#]
pub struct MelodyParser;

fn main() {
    let input = "\"";
    match MelodyParser::parse(Rule::root, input) {
        Ok(pairs) => println!("OK"),
        Err(e) => println!("Error: {}", e),
    }
}
EOF
cd /tmp/test_proj && cargo run --offline"}

