                    '`' => unescaped.push('`'),
                    '\\' => unescaped.push('\\'),
                    other => {
                        unescaped.push('\\');
                        unescaped.push(other);
                    }
                }
            } else {
                unescaped.push('\\');
            }
        } else {
            unescaped.push(c);
        }
    }

    Some(Node::Raw(unescaped))
}
