use pest::iterators::Pair;
use pest::Parser;
use pest_derive::Parser;

use super::ast::*;

#[derive(Parser)]
#[grammar = "compiler/grammar.pest"]
pub struct MelodyParser;

pub fn parse(source: &str) -> Result<Vec<Node>, pest::error::Error<Rule>> {
    let pairs = MelodyParser::parse(Rule::root, source)?;
    let mut ast = Vec::new();

    for pair in pairs {
        if pair.as_rule() == Rule::root {
            for inner in pair.into_inner() {
                if inner.as_rule() == Rule::statement {
                    if let Some(node) = parse_statement(inner) {
                        ast.push(node);
                    }
                }
            }
        }
    }

    Ok(ast)
}

fn parse_statement(pair: Pair<Rule>) -> Option<Node> {
    let inner = pair.into_inner().next()?;
    match inner.as_rule() {
        Rule::variable_declaration => parse_variable_declaration(inner),
        Rule::variable_invocation => parse_variable_invocation(inner),
        Rule::quantifier => parse_quantifier(inner),
        Rule::group_declaration => parse_group_declaration(inner),
        Rule::assertion_declaration => parse_assertion_declaration(inner),
        Rule::not_statement => parse_not_statement(inner),
        Rule::range_statement => parse_range_statement(inner),
        Rule::symbol_statement => parse_symbol_statement(inner),
        Rule::literal_statement => parse_literal_statement(inner),
        Rule::raw_statement => parse_raw_statement(inner),
        _ => None,
    }
}

fn parse_variable_declaration(pair: Pair<Rule>) -> Option<Node> {
    let mut inner = pair.into_inner();
    let name_pair = inner.next()?;
    let name = name_pair.as_str().to_string();
    let block_pair = inner.next()?;
    let statements = parse_block(block_pair);
    Some(Node::VariableDeclaration { name, statements })
}

fn parse_variable_invocation(pair: Pair<Rule>) -> Option<Node> {
    let name_pair = pair.into_inner().next()?;
    Some(Node::VariableInvocation(name_pair.as_str().to_string()))
}

fn parse_block(pair: Pair<Rule>) -> Vec<Node> {
    let mut statements = Vec::new();
    for inner in pair.into_inner() {
        if inner.as_rule() == Rule::statement {
            if let Some(node) = parse_statement(inner) {
                statements.push(node);
            }
        }
    }
    statements
}

fn parse_quantifier(pair: Pair<Rule>) -> Option<Node> {
    let mut inner = pair.into_inner();
    let mut lazy = false;
    let mut next = inner.next()?;

    if next.as_rule() == Rule::lazy {
        lazy = true;
        next = inner.next()?;
    }

    let amount = parse_amount(next)?;
    let elem_pair = inner.next()?;

    let element = match elem_pair.as_rule() {
        Rule::group_declaration => parse_group_declaration(elem_pair)?,
        Rule::assertion_declaration => parse_assertion_declaration(elem_pair)?,
        Rule::symbol_statement => parse_symbol_statement(elem_pair)?,
        Rule::range_statement => parse_range_statement(elem_pair)?,
        Rule::literal_statement => parse_literal_statement(elem_pair)?,
        Rule::raw_statement => parse_raw_statement(elem_pair)?,
        Rule::not_statement => parse_not_statement(elem_pair)?,
        Rule::variable_invocation => parse_variable_invocation(elem_pair)?,
        _ => return None,
    };

    Some(Node::Quantifier {
        lazy,
        amount,
        element: Box::new(element),
    })
}

fn parse_amount(pair: Pair<Rule>) -> Option<Amount> {
    let inner = pair.into_inner().next()?;
    match inner.as_rule() {
        Rule::integer => {
            let val = inner.as_str().parse().ok()?;
            Some(Amount::Exact(val))
        }
        Rule::range_amount => {
            let mut parts = inner.into_inner();
            let start = parts.next()?.as_str().parse().ok()?;
            let end = parts.next()?.as_str().parse().ok()?;
            Some(Amount::Range(start, end))
        }
        _ => match inner.as_str() {
            "some" => Some(Amount::Some),
            "any" => Some(Amount::Any),
            "option" => Some(Amount::Option),
            _ => None,
        },
    }
}

fn parse_group_declaration(pair: Pair<Rule>) -> Option<Node> {
    let mut inner = pair.into_inner();
    let keyword_pair = inner.next()?;
    let keyword = keyword_pair.as_str();

    match keyword {
        "match" => {
            let block_pair = inner.next()?;
            let statements = parse_block(block_pair);
            Some(Node::Group {
                group_type: GroupType::Match,
                name: None,
                statements,
            })
        }
        "either" => {
            let block_pair = inner.next()?;
            let statements = parse_block(block_pair);
            Some(Node::Group {
                group_type: GroupType::Either,
                name: None,
                statements,
            })
        }
        "capture" => {
            let mut name = None;
            let mut next = inner.next()?;
            if next.as_rule() == Rule::group_name {
                name = Some(next.as_str().to_string());
                next = inner.next()?;
            }
            let statements = parse_block(next);
            Some(Node::Group {
                group_type: GroupType::Capture,
                name,
                statements,
            })
        }
        _ => None,
    }
}

fn parse_assertion_declaration(pair: Pair<Rule>) -> Option<Node> {
    let mut inner = pair.into_inner();
    let mut not = false;
    let mut next = inner.next()?;

    if next.as_str() == "not" {
        not = true;
        next = inner.next()?;
    }

    let type_str = next.as_str();
    let assertion_type = match type_str {
        "ahead" => AssertionType::Ahead,
        "behind" => AssertionType::Behind,
        _ => return None,
    };

    let block_pair = inner.next()?;
    let statements = parse_block(block_pair);

    Some(Node::Assertion {
        not,
        assertion_type,
        statements,
    })
}

fn parse_not_statement(pair: Pair<Rule>) -> Option<Node> {
    let inner = pair.into_inner().next()?;
    match inner.as_rule() {
        Rule::symbol_content => {
            let sym = parse_symbol_name(&inner)?;
            Some(Node::Not(NotElement::Symbol(sym)))
        }
        Rule::range_content => {
            let (start, end) = parse_range_bounds(inner)?;
            Some(Node::Not(NotElement::Range { start, end }))
        }
