    let range_content = pair.into_inner().next()?;
    let (start, end) = parse_range_bounds(range_content)?;
    Some(Node::Range { start, end })
}

fn parse_range_bounds(pair: Pair<Rule>) -> Option<(String, String)> {
    let mut inner = pair.into_inner();
    let start = inner.next()?.as_str().to_string();
    let end = inner.next()?.as_str().to_string();
    Some((start, end))
}

fn parse_symbol_statement(pair: Pair<Rule>) -> Option<Node> {
    let symbol_content = pair.into_inner().next()?;
    let sym = parse_symbol_name(&symbol_content)?;
    Some(Node::Symbol(sym))
