{"command":"cat <<'EOF' > src/compiler/transpile.rs
use std::collections::HashMap;
use super::ast::*;
use super::errors::CompilerError;

#[derive(Default, Clone)]
pub struct Scope {
    variables: HashMap<String, Vec<Node>>,
}

pub fn transpile(nodes: &[Node]) -> Result<String, CompilerError> {
    let mut scope = Scope::default();
    transpile_nodes(nodes, &mut scope)
}

pub fn transpile_nodes(nodes: &[Node], scope: &mut Scope) -> Result<String, CompilerError> {
    let mut result = String::new();
    for node in nodes {
        result.push_str(&transpile_node(node, scope)?);
    }
    Ok(result)
}

fn transpile_node(node: &Node, scope: &mut Scope) -> Result<String, CompilerError> {
    match node {
        Node::VariableDeclaration { name, statements } => {
            scope.variables.insert(name.clone(), statements.clone());
            Ok(String::new())
        }
        Node::VariableInvocation(name) => {
            if let Some(stmts) = scope.variables.get(name).cloned() {
                transpile_nodes(&stmts, scope)
            } else {
                Err(CompilerError::UninitializedVariable)
            }
        }
        Node::Literal(text) => Ok(escape_literal(text)),
        Node::Raw(text) => Ok(text.clone()),
        Node::Symbol(sym) => transpile_symbol(sym),
        Node::Not(not_elem) => transpile_not(not_elem),
        Node::Range { start, end } => Ok(format!("[{}-{}]", start, end)),
        Node::Group {
            group_type,
            name,
            statements,
        } => transpile_group(group_type, name.as_deref(), statements, scope),
        Node::Assertion {
            not,
            assertion_type,
            statements,
        } => {
            let inner = transpile_nodes(statements, scope)?;
            let prefix = match (not, assertion_type) {
                (false, AssertionType::Ahead) => "(?=",
                (true, AssertionType::Ahead) => "(?!",
                (false, AssertionType::Behind) => "(?<=",
                (true, AssertionType::Behind) => "(?<!",
            };
            Ok(format!("{}{})", prefix, inner))
        }
        Node::Quantifier {
            lazy,
            amount,
            element,
        } => transpile_quantifier(*lazy, amount, element, scope),
    }
}

fn escape_literal(s: &str) -> String {
    let mut escaped = String::new();
    for c in s.chars() {
        match c {
            '.' | '+' | '*' | '?' | '(' | ')' | '[' | ']' | '{' | '}' | '^' | '$' | '\\' | '|' => {
                escaped.push('\\');
                escaped.push(c);
            }
            _ => escaped.push(c),
        }
    }
    escaped
}

fn transpile_symbol(sym: &str) -> Result<String, CompilerError> {
    match sym {
        "char" => Ok(".".to_string()),
        "space" => Ok(" ".to_string()),
        "whitespace" => Ok("\\s".to_string()),
        "digit" => Ok("\\d".to_string()),
        "word" => Ok("\\w".to_string()),
        "feed" => Ok("\\f".to_string()),
        "newline" => Ok("\\n".to_string()),
        "return" => Ok("\\r".to_string()),
        "tab" => Ok("\\t".to_string()),
        "vertical" => Ok("\\v".to_string()),
        "null" => Ok("\\0".to_string()),
        "backspace" => Ok("[\\b]".to_string()),
        "boundary" => Ok("\\b".to_string()),
        "alphabetic" => Ok("[a-zA-Z]".to_string()),
        "alphanumeric" => Ok("[a-zA-Z0-9]".to_string()),
        "start" => Ok("^".to_string()),
        "end" => Ok("$".to_string()),
        _ => Err(CompilerError::UnrecognizedSymbol),
    }
}

fn transpile_not(elem: &NotElement) -> Result<String, CompilerError> {
    match elem {
        NotElement::Symbol(sym) => match sym.as_str() {
            "digit" => Ok("\\D".to_string()),
            "whitespace" => Ok("\\S".to_string()),
            "word" => Ok("\\W".to_string()),
            "boundary" => Ok("\\B".to_string()),
            "space" => Ok("[^ ]".to_string()),
            "alphabetic" => Ok("[^a-zA-Z]".to_string()),
            "alphanumeric" => Ok("[^a-zA-Z0-9]".to_string()),
            "feed" => Ok("[^\\f]".to_string()),
            "newline" => Ok("[^\\n]".to_string()),
            "return" => Ok("[^\\r]".to_string()),
            "tab" => Ok("[^\\t]".to_string()),
            "vertical" => Ok("[^\\v]".to_string()),
            "null" => Ok("[^\\0]".to_string()),
            "backspace" => Ok("[^\\b]".to_string()),
            "char" => Err(CompilerError::NegativeChar),
            "start" => Err(CompilerError::NegativeStart),
            "end" => Err(CompilerError::NegativeEnd),
            _ => Err(CompilerError::UnrecognizedSymbol),
        },
        NotElement::Range { start, end } => Ok(format!("[^{}-{}]", start, end)),
    }
}

fn transpile_group(
    group_type: &GroupType,
    name: Option<&str>,
    statements: &[Node],
    scope: &mut Scope,
) -> Result<String, CompilerError> {
    if statements.is_empty() {
        return Ok(String::new());
    }

    match group_type {
        GroupType::Match => {
            let inner = transpile_nodes(statements, scope)?;
            Ok(format!("(?:{})", inner))
        }
        GroupType::Either => {
            let mut branches = Vec::new();
            for stmt in statements {
                branches.push(transpile_node(stmt, scope)?);
            }
            Ok(format!("(?:{})", branches.join("|")))
        }
        GroupType::Capture => {
            let inner = transpile_nodes(statements, scope)?;
            if let Some(n) = name {
                Ok(format!("(?<{}>{})", n, inner))
            } else {
                Ok(format!("({})", inner))
            }
        }
    }
}

fn transpile_quantifier(
    lazy: bool,
    amount: &Amount,
    element: &Node,
    scope: &mut Scope,
) -> Result<String, CompilerError> {
    if let Node::VariableInvocation(_) = element {
        return Err(CompilerError::UnexpectedVariableInvocationInQuantifier);
    }

    let inner = transpile_node(element, scope)?;
    let needs_grouping = match element {
        Node::Literal(s) | Node::Raw(s) => s.chars().count() > 1,
        Node::Group { .. } => false,
        _ => false,
    };

    let target = if needs_grouping {
        format!("(?:{})", inner)
    } else {
        inner
    };

    let suffix = match amount {
        Amount::Exact(n) => format!("{{{}}}", n),
        Amount::Range(min, max) => format!("{{{},{}}}", min, max),
        Amount::Some => "+".to_string(),
        Amount::Any => "*".to_string(),
        Amount::Option => "?".to_string(),
    };

    let lazy_suffix = if lazy { "?" } else { "" };
    Ok(format!("{}{}{}", target, suffix, lazy_suffix))
}
EOF"}

