use std::io::{self, BufRead, Write};
use is_terminal_polyfill::IsTerminal;
use colored::Colorize;
use crate::compiler::compile;

pub fn start_repl(no_color: bool) {
    let stdin = io::stdin();
    let stdout = io::stdout();

    if !stdin.is_terminal() || !stdout.is_terminal() {
        let err_msg = "Error: repl argument supplied with piped input or output\n";
        if io::stderr().is_terminal() && !no_color {
            eprint!("{}", err_msg.bright_red());
        } else {
            eprint!("{}", err_msg);
        }
        std::process::exit(64);
    }

    let use_color = stdout.is_terminal() && !no_color;

    if use_color {
        println!("{}", "Melody REPL v0.20.0".bright_green());
        println!();
        println!("{}", "Commands:".bright_green());
        println!();
        println!("- {} - {}", ":u, :undo".bright_blue(), "undo the latest line".bright_green());
        println!("- {} - {}", ":r, :redo".bright_blue(), "redo the latest undo".bright_green());
        println!("- {} - {}", ":c, :clear".bright_blue(), "clear all REPL history and previous input".bright_green());
        println!("- {} - {}", ":s, :source".bright_blue(), "print all previously entered lines".bright_green());
        println!("- {} - {}", ":e, :exit".bright_blue(), "exit the REPL".bright_green());
        println!();
    } else {
        println!("Melody REPL v0.20.0");
        println!();
        println!("Commands:");
        println!();
        println!("- :u, :undo - undo the latest line");
        println!("- :r, :redo - redo the latest undo");
        println!("- :c, :clear - clear all REPL history and previous input");
        println!("- :s, :source - print all previously entered lines");
        println!("- :e, :exit - exit the REPL");
        println!();
    }

    let mut accumulated_lines: Vec<String> = Vec::new();
    let mut undo_stack: Vec<Vec<String>> = Vec::new();

    let mut handle = stdin.lock();

    loop {
        if use_color {
            print!("{}", "~ ".bright_blue());
        } else {
            print!("~ ");
        }
        let _ = io::stdout().flush();

        let mut line = String::new();
        let bytes_read = match handle.read_line(&mut line) {
            Ok(bytes) => bytes,
            Err(_) => break,
        };

        if bytes_read == 0 {
            // EOF reached
            std::process::exit(101);
        }

        let trimmed = line.trim();

        if trimmed.starts_with(':') {
            match trimmed {
                ":e" | ":exit" => {
                    if use_color {
                        println!("{}", "exit".bright_green());
                    } else {
                        println!("exit");
                    }
                    std::process::exit(0);
                }
                ":u" | ":undo" => {
                    if use_color {
                        println!("{}", "undo".bright_green());
                    } else {
                        println!("undo");
                    }
                    if accumulated_lines.is_empty() {
                        if use_color {
                            println!("{}", "nothing to undo".bright_red());
                        } else {
                            println!("nothing to undo");
                        }
                    } else {
                        undo_stack.push(accumulated_lines.clone());
                        accumulated_lines.pop();
                        let source = accumulated_lines.join("\n");
                        match compile(&source) {
                            Ok(res) => {
                                if use_color {
                                    println!("{}", res.bright_blue());
                                } else {
                                    println!("{}", res);
                                }
                            }
                            Err(e) => {
                                if use_color {
                                    println!("{}", e.to_string().bright_red());
                                } else {
                                    println!("{}", e);
                                }
                            }
                        }
                    }
                    println!();
                }
                ":r" | ":redo" => {
                    if use_color {
                        println!("{}", "redo".bright_green());
                    } else {
                        println!("redo");
                    }
                    if let Some(prev) = undo_stack.pop() {
                        accumulated_lines = prev;
                        let source = accumulated_lines.join("\n");
                        match compile(&source) {
                            Ok(res) => {
                                if use_color {
                                    println!("{}", res.bright_blue());
                                } else {
                                    println!("{}", res);
                                }
                            }
                            Err(e) => {
                                if use_color {
                                    println!("{}", e.to_string().bright_red());
                                } else {
                                    println!("{}", e);
                                }
                            }
                        }
                    } else {
                        if use_color {
                            println!("{}", "nothing to redo".bright_red());
                        } else {
                            println!("nothing to redo");
                        }
                    }
                    println!();
                }
                ":c" | ":clear" => {
                    if use_color {
                        println!("{}", "clear".bright_green());
                    } else {
                        println!("clear");
                    }
                    accumulated_lines.clear();
                    undo_stack.clear();
                    println!();
                }
                ":s" | ":source" => {
                    if use_color {
                        println!("{}", "source".bright_green());
                    } else {
                        println!("source");
                    }
                    if accumulated_lines.is_empty() {
                        if use_color {
                            println!("{}", "no lines to print".bright_red());
                        } else {
                            println!("no lines to print");
                        }
                    } else {
                        for (i, line_str) in accumulated_lines.iter().enumerate() {
                            if use_color {
                                println!("{} {}", format!("{}", i + 1).dimmed(), line_str.bright_blue());
                            } else {
                                println!("{} {}", i + 1, line_str);
                            }
                        }
                    }
                    println!();
                }
                cmd => {
                    if use_color {
                        println!("{} {} {}", "Error:".bright_red(), "unrecognized command".bright_red(), format!("\"{}\"", cmd).bright_blue());
                    } else {
                        println!("Error: unrecognized command \"{}\"", cmd);
                    }
                    println!();
                }
            }
        } else {
            undo_stack.clear();
            let mut test_lines = accumulated_lines.clone();
            test_lines.push(line.trim_end().to_string());
            let source = test_lines.join("\n");

            match compile(&source) {
                Ok(res) => {
                    accumulated_lines.push(line.trim_end().to_string());
                    if use_color {
                        println!("{}", res.bright_blue());
                    } else {
                        println!("{}", res);
                    }
                }
                Err(e) => {
                    if use_color {
                        println!("{}", e.to_string().bright_red());
                    } else {
                        println!("{}", e);
                    }
                }
            }
            println!();
        }
    }
}
EOF"}

