    let source = if let Some(path_str) = &args.input_file_path {
        if path_str == "-" {
            if io::stdin().is_terminal() {
                print_no_input_error(args.no_color);
                std::process::exit(66);
            }
            read_stdin()
        } else {
            match fs::read_to_string(path_str) {
