                Err(_) => {
                    print_error(&format!("unable read file at path {}", path_str), args.no_color);
                    std::process::exit(65);
                }
            }
        }
    } else {
        if io::stdin().is_terminal() {
            print_no_input_error(args.no_color);
            std::process::exit(66);
        }
        read_stdin()
    };

    // Compile source
    let compiled_regex = match compile(&source) {
        Ok(res) => res,
        Err(e) => {
            print_error(&e.to_string(), args.no_color);
            std::process::exit(65);
        }
    };

    // Check output file
    if let Some(out_path) = &args.output {
        if let Err(_) = fs::write(out_path, compiled_regex.as_bytes()) {
            print_error(out_path, args.no_color);
            std::process::exit(74);
        }
        return;
    }

