            format!("{}...", test_str.chars().take(10).collect::<String>())
        } else {
            test_str.clone()
        };

        let use_color = io::stdout().is_terminal() && !args.no_color;
        if is_match {
            if use_color {
                println!("'{}' {}", display_str, "matched".bright_green());
            } else {
                println!("'{}' matched", display_str);
            }
        } else {
            if use_color {
                println!("'{}' {}", display_str, "did not match".bright_red());
            } else {
                println!("'{}' did not match", display_str);
            }
        }
        return;
    }

    // Check test file
    if let Some(test_file_path) = &args.test_file {
        let test_file_contents = match fs::read_to_string(test_file_path) {
            Ok(s) => s,
            Err(_) => {
                print_error(&format!("unable read file at path {}", test_file_path), args.no_color);
                std::process::exit(74);
            }
        };

        let regex = match Regex::new(&compiled_regex) {
            Ok(r) => r,
            Err(e) => {
                let err_msg = format!("Error: could not compile regex\nCause: {}\nRegex: {}", e, compiled_regex);
                print_raw_error(&err_msg, args.no_color);
                std::process::exit(65);
            }
        };

        let is_match = regex.is_match(&test_file_contents).unwrap_or(false);
        let use_color = io::stdout().is_terminal() && !args.no_color;

        if is_match {
            if use_color {
                println!("{} {}", test_file_path, "matched".bright_green());
            } else {
                println!("{} matched", test_file_path);
            }
        } else {
            if use_color {
                println!("{} {}", test_file_path, "did not match".bright_red());
            } else {
                println!("{} did not match", test_file_path);
            }
        }
        return;
    }

    // Print compiled regex to stdout
    let use_color = io::stdout().is_terminal() && !args.no_color;
    if use_color {
        println!("{}", compiled_regex.bright_blue());
    } else {
        println!("{}", compiled_regex);
    }
}

fn read_stdin() -> String {
    let mut buffer = String::new();
    let _ = io::stdin().read_to_string(&mut buffer);
    buffer
}

fn print_error(msg: &str, no_color: bool) {
    let full_msg = if msg.starts_with("Error:") {
        msg.to_string()
    } else {
        format!("Error: {}", msg)
    };
    print_raw_error(&full_msg, no_color);
}

fn print_raw_error(msg: &str, no_color: bool) {
    if io::stderr().is_terminal() && !no_color {
        eprintln!("{}", msg.bright_red());
    } else {
        eprintln!("{}", msg);
    }
}

fn print_no_input_error(no_color: bool) {
    let msg = "No input file supplied and no input piped\nTry adding a path argument: 'melody ./file.mdy'";
    if io::stdout().is_terminal() && !no_color {
        println!("{}", msg.bright_blue());
    } else {
        println!("{}", msg);
    }
    println!();
    let mut cmd = Args::command();
    let _ = cmd.print_help();
    println!();
}
