    Some((start, end))
}

fn parse_symbol_statement(pair: Pair<Rule>) -> Option<Node> {
    let symbol_content = pair.into_inner().next()?;
    let sym = parse_symbol_name(&symbol_content)?;
    Some(Node::Symbol(sym))
}

fn parse_symbol_name(pair: &Pair<Rule>) -> Option<String> {
    let s = pair.as_str();
    if s.starts_with('<') && s.ends_with('>') {
        Some(s[1..s.len() - 1].to_string())
    } else {
        None
    }
}

fn parse_literal_statement(pair: Pair<Rule>) -> Option<Node> {
    let literal_content = pair.into_inner().next()?;
    let raw_text = literal_content.as_str();
    let quote = raw_text.chars().next()?;
    let inner_text = &raw_text[1..raw_text.len() - 1];

    let mut unescaped = String::new();
    let mut chars = inner_text.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(next_c) = chars.next() {
                match next_c {
                    'n' => unescaped.push('\n'),
                    'r' => unescaped.push('\r'),
                    't' => unescaped.push('\t'),
                    '\\' => unescaped.push('\\'),
                    '\"' if quote == '"' => unescaped.push('\"'),
                    '\'' if quote == '\'' => unescaped.push('\''),
                    other => {
                        unescaped.push('\\');
                        unescaped.push(other);
                    }
                }
            } else {
                unescaped.push('\\');
            }
        } else {
            unescaped.push(c);
        }
    }

    Some(Node::Literal(unescaped))
}

fn parse_raw_statement(pair: Pair<Rule>) -> Option<Node> {
    let raw_content = pair.into_inner().next()?;
    let raw_text = raw_content.as_str();
    let inner_text = &raw_text[1..raw_text.len() - 1];

    let mut unescaped = String::new();
    let mut chars = inner_text.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(next_c) = chars.next() {
                match next_c {
                    '`' => unescaped.push('`'),
                    '\\' => unescaped.push('\\'),
                    other => {
                        unescaped.push('\\');
                        unescaped.push(other);
                    }
                }
            } else {
                unescaped.push('\\');
            }
        } else {
            unescaped.push(c);
        }
    }

    Some(Node::Raw(unescaped))
}
